#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/generate/generate-agents-manifest.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
// generate-agents-manifest — auto-emits /agents.json + /agents.txt at
// build time. Walks every `<feature>/__specs__/spec.yaml` under src/
// and composes the canonical machine-readable manifest + a plain-text
// index for human / browser-extension consumers.
//
// Per AGENT_AFFORDANCES.yaml.agents_index: both files are GENERATED;
// hand-maintaining either is forbidden, since the source specs ARE the
// contract and the manifest must never drift.
//
// Behavior:
//   1. Parses spec.yaml files with the `yaml` package (devDep across
//      every primitive).
//   2. Emits BOTH agents.json (machine-readable manifest) and agents.txt
//      (plain-text per-feature blocks; grep-friendly index per
//      SPEC_CONTRACT public_surface).
//   3. Walks `src/` only by default; pass the repo root to override.
//
// Dep: requires `yaml` (npm `yaml` package) as a devDependency.
//
// Usage:
//   node scripts/build/generate-agents-manifest.mjs [<repo-root>]
//
// Defaults to `process.cwd()` as the repo root + writes to
// <root>/public/agents.json + <root>/public/agents.txt.
//
// Exit codes:
//   0 — manifest written (or no specs found in a greenfield repo)
//   1 — one or more specs failed validation (no manifest written)
import { mkdirSync, writeFileSync, readFileSync, existsSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { createRequire } from "node:module";

import { listAllFiles } from "../lib/walk.mjs";

const require = createRequire(import.meta.url);
let YAML;
try {
  YAML = require("yaml");
} catch {
  process.stderr.write(
    "❌ generate-agents-manifest: missing `yaml` devDependency.\n" +
      "   Install it:  pnpm add -D yaml\n",
  );
  process.exit(1);
}

const REPO_ROOT = resolve(process.argv[2] ?? process.cwd());
const SOURCE_ROOTS = ["src"];
const OUT_JSON = resolve(REPO_ROOT, "public", "agents.json");
const OUT_TXT = resolve(REPO_ROOT, "public", "agents.txt");
const OUT_LLMS = resolve(REPO_ROOT, "public", "llms.txt");

/**
 * Reads the primitive's name + description from the project's
 * package.json. Falls back gracefully when fields are missing so the
 * generator works in a greenfield repo.
 *
 * @param {string} rootDir absolute repo root
 * @returns {{ name: string, description: string }}
 */
export function readPrimitiveMeta(rootDir) {
  const pkgPath = resolve(rootDir, "package.json");
  if (!existsSync(pkgPath)) {
    return { name: "unknown-primitive", description: "" };
  }
  let pkg;
  try {
    pkg = JSON.parse(readFileSync(pkgPath, "utf-8"));
  } catch {
    return { name: "unknown-primitive", description: "" };
  }
  const rawName = typeof pkg.name === "string" ? pkg.name : "unknown-primitive";
  // Strip common reverse-domain prefix (e.g., `com.example.audit-web` → `audit`)
  // and a `-web` suffix when the package is the web surface of a primitive.
  const shortName = rawName
    .replace(/^[a-z]+\.[a-z][a-z0-9-]*\./, "")
    .replace(/-web$/, "");
  const description = typeof pkg.description === "string" ? pkg.description : "";
  return { name: shortName, description };
}

/**
 * Walks `rootDir` for every `__specs__/spec.yaml`.
 *
 * @param {string} rootDir
 * @param {ReadonlyArray<string>} sourceRoots
 * @returns {string[]}
 */
export function listSpecFiles(rootDir, sourceRoots) {
  const out = [];
  for (const sub of sourceRoots) {
    const abs = resolve(rootDir, sub);
    if (!existsSync(abs)) continue;
    for (const file of listAllFiles(abs)) {
      if (file.endsWith("/__specs__/spec.yaml")) out.push(file);
    }
  }
  out.sort();
  return out;
}

/**
 * @typedef {{
 *   feature_name: string,
 *   operation: { name: string, slug: string, description: string },
 *   invocation: { type: string, method?: string, path?: string },
 *   chat_agent: {
 *     when_to_call: string,
 *     when_not_to_call: string,
 *     natural_language_examples: string[],
 *     confirm_before: string,
 *     summarize_after_success: string,
 *     summarize_after_failure: string,
 *   },
 *   cross_cutting: { wcag: string, auth: string, mobile: string, i18n: string },
 *   links: { flows: string[], tests: string[], manual?: string[], openapi?: string, asyncapi?: string },
 *   spec_path: string,
 * }} iAgentsEntry
 */

/**
 * Maps a parsed spec.yaml object into the manifest-entry shape.
 *
 * @param {Record<string, unknown>} parsed
 * @param {string} specPath absolute path (for the manifest's `spec_path`)
 * @param {string} rootDir absolute repo root (for relativizing spec_path)
 * @returns {{ ok: true, entry: iAgentsEntry } | { ok: false, error: string }}
 */
export function toAgentsEntry(parsed, specPath, rootDir) {
  const errors = [];
  const stringField = (obj, key) => {
    const v = obj?.[key];
    return typeof v === "string" ? v : "";
  };
  const stringList = (obj, key) => {
    const v = obj?.[key];
    return Array.isArray(v) && v.every((x) => typeof x === "string") ? v : [];
  };

  if (typeof parsed.feature_name !== "string" || !parsed.feature_name) {
    errors.push("missing or non-scalar `feature_name`");
  }
  if (!parsed.operation || typeof parsed.operation !== "object" || Array.isArray(parsed.operation)) {
    errors.push("missing or non-map `operation`");
  }
  if (!parsed.invocation || typeof parsed.invocation !== "object" || Array.isArray(parsed.invocation)) {
    errors.push("missing or non-map `invocation`");
  }
  if (!parsed.chat_agent || typeof parsed.chat_agent !== "object" || Array.isArray(parsed.chat_agent)) {
    errors.push("missing or non-map `chat_agent`");
  }
  if (!parsed.cross_cutting || typeof parsed.cross_cutting !== "object" || Array.isArray(parsed.cross_cutting)) {
    errors.push("missing or non-map `cross_cutting`");
  }
  if (!parsed.links || typeof parsed.links !== "object" || Array.isArray(parsed.links)) {
    errors.push("missing or non-map `links`");
  }

  if (errors.length > 0) {
    return { ok: false, error: errors.join("; ") };
  }

  /** @type {iAgentsEntry} */
  const entry = {
    feature_name: parsed.feature_name,
    operation: {
      name: stringField(parsed.operation, "name"),
      slug: stringField(parsed.operation, "slug"),
      description: stringField(parsed.operation, "description"),
    },
    invocation: {
      type: stringField(parsed.invocation, "type"),
      ...(parsed.invocation.method && { method: stringField(parsed.invocation, "method") }),
      ...(parsed.invocation.path && { path: stringField(parsed.invocation, "path") }),
    },
    chat_agent: {
      when_to_call: stringField(parsed.chat_agent, "when_to_call"),
      when_not_to_call: stringField(parsed.chat_agent, "when_not_to_call"),
      natural_language_examples: stringList(parsed.chat_agent, "natural_language_examples"),
      confirm_before: stringField(parsed.chat_agent, "confirm_before"),
      summarize_after_success: stringField(parsed.chat_agent, "summarize_after_success"),
      summarize_after_failure: stringField(parsed.chat_agent, "summarize_after_failure"),
    },
    cross_cutting: {
      wcag: stringField(parsed.cross_cutting, "wcag"),
      auth: stringField(parsed.cross_cutting, "auth"),
      mobile: stringField(parsed.cross_cutting, "mobile"),
      i18n: stringField(parsed.cross_cutting, "i18n"),
    },
    links: {
      flows: stringList(parsed.links, "flows"),
      tests: stringList(parsed.links, "tests"),
      ...(parsed.links.manual && { manual: stringList(parsed.links, "manual") }),
      ...(parsed.links.openapi && { openapi: stringField(parsed.links, "openapi") }),
      ...(parsed.links.asyncapi && { asyncapi: stringField(parsed.links, "asyncapi") }),
    },
    spec_path: relative(rootDir, specPath),
  };
  return { ok: true, entry };
}

/**
 * Aggregates every spec.yaml into the manifest entries.
 *
 * @param {string} rootDir
 * @param {ReadonlyArray<string>} sourceRoots
 * @returns {{ entries: iAgentsEntry[], failures: Array<{ filePath: string, reason: string, detail: string }> }}
 */
export function aggregate(rootDir, sourceRoots) {
  const specs = listSpecFiles(rootDir, sourceRoots);
  const entries = [];
  const failures = [];
  for (const file of specs) {
    let contents;
    try {
      contents = readFileSync(file, "utf-8");
    } catch (err) {
      failures.push({
        filePath: file,
        reason: "cannot read file",
        detail: err instanceof Error ? err.message : String(err),
      });
      continue;
    }
    let parsed;
    try {
      parsed = YAML.parse(contents);
    } catch (err) {
      failures.push({
        filePath: file,
        reason: "YAML parse error",
        detail: err instanceof Error ? err.message : String(err),
      });
      continue;
    }
    if (!parsed || typeof parsed !== "object") {
      failures.push({
        filePath: file,
        reason: "non-object YAML root",
        detail: "spec.yaml must be a mapping at the top level",
      });
      continue;
    }
    const mapped = toAgentsEntry(parsed, file, rootDir);
    if (!mapped.ok) {
      failures.push({
        filePath: file,
        reason: "incomplete spec.yaml",
        detail: mapped.error,
      });
      continue;
    }
    entries.push(mapped.entry);
  }
  entries.sort((a, b) => a.feature_name.localeCompare(b.feature_name));
  return { entries, failures };
}

/**
 * Renders the manifest as canonical JSON. Deterministic — no
 * generated_at timestamp; the entries list IS the manifest.
 *
 * @param {iAgentsEntry[]} entries
 * @returns {string}
 */
export function renderJson(entries) {
  return `${JSON.stringify({ version: 1, features: entries }, null, 2)}\n`;
}

/**
 * Renders the manifest as plain text — one block per feature, grep-
 * friendly. Per AGENT_AFFORDANCES /llms.txt: this is the
 * file a browser-extension AI or human reader hits first.
 *
 * @param {iAgentsEntry[]} entries
 * @returns {string}
 */
export function renderText(entries) {
  const out = [];
  out.push("# Primitive — agents.txt");
  out.push("# Auto-generated from every <feature>/__specs__/spec.yaml.");
  out.push("# Plain-text index of operations a chat agent can invoke.");
  out.push("# For the structured manifest see /agents.json.");
  out.push("");
  out.push(`# features: ${String(entries.length)}`);
  out.push("");
  for (const e of entries) {
    const verb =
      e.invocation.type === "http" && e.invocation.method
        ? `${e.invocation.method} ${e.invocation.path ?? ""}`
        : e.invocation.type === "ui" && e.invocation.path
          ? `UI ${e.invocation.path}`
          : `(${e.invocation.type})`;
    out.push(`[${e.feature_name}] ${verb}  permission=${e.operation.slug}`);
    out.push(`    operation: ${e.operation.name}`);
    out.push(`    description: ${e.operation.description}`);
    out.push(`    when_to_call: ${e.chat_agent.when_to_call}`);
    out.push(`    when_not_to_call: ${e.chat_agent.when_not_to_call}`);
    if (e.chat_agent.natural_language_examples.length > 0) {
      out.push(`    examples:`);
      for (const ex of e.chat_agent.natural_language_examples) {
        out.push(`      - ${ex}`);
      }
    }
    out.push(`    confirm_before: ${e.chat_agent.confirm_before}`);
    out.push(`    summarize_after_success: ${e.chat_agent.summarize_after_success}`);
    out.push(`    summarize_after_failure: ${e.chat_agent.summarize_after_failure}`);
    out.push(`    auth: ${e.cross_cutting.auth}`);
    out.push(`    spec: ${e.spec_path}`);
    if (e.links.openapi) out.push(`    openapi: ${e.links.openapi}`);
    if (e.links.manual && e.links.manual.length > 0) {
      out.push(`    manual: ${e.links.manual.join(", ")}`);
    }
    out.push("");
  }
  return out.join("\n");
}

/**
 * Renders the site-root /llms.txt index per https://llmstxt.org/.
 * Per AGENT_AFFORDANCES /llms.txt: required at site root;
 * plain text; index of operations + docs URLs + manual-script URLs.
 *
 * This is the FIRST file an LLM should read when it arrives at the
 * site. It points at the deeper artifacts (/agents.json + /agents.txt +
 * per-feature openapi/manual paths).
 *
 * @param {iAgentsEntry[]} entries
 * @param {{ name: string, description: string }} primitive
 * @returns {string}
 */
export function renderLlmsTxt(entries, primitive) {
  const out = [];
  out.push(`# ${primitive.name} primitive`);
  out.push("");
  out.push(
    `> ${primitive.description || `${primitive.name} primitive.`}`,
  );
  out.push("");
  out.push(
    `This primitive exposes ${entries.length} agent-callable operation(s). Every operation is spec'd at \`<feature>/__specs__/spec.yaml\` and surfaced via the machine-readable manifest at \`/agents.json\`.`,
  );
  out.push("");
  out.push("## Agent surfaces");
  out.push("");
  out.push("- [/agents.json](/agents.json): canonical machine-readable manifest. Every operation's invocation + chat_agent metadata + cross_cutting concerns + links to flows/tests/manual/openapi.");
  out.push("- [/agents.txt](/agents.txt): grep-friendly plain-text index of the same manifest.");
  out.push("");
  out.push("## Operations");
  out.push("");
  for (const e of entries) {
    const verb =
      e.invocation.type === "http" && e.invocation.method
        ? `${e.invocation.method} ${e.invocation.path ?? ""}`
        : e.invocation.type === "ui" && e.invocation.path
          ? `UI ${e.invocation.path}`
          : `(${e.invocation.type})`;
    out.push(`- **${e.feature_name}** — ${verb}: ${e.operation.description}`);
  }
  out.push("");
  out.push("## Conventions");
  out.push("");
  out.push("- All HTTP responses use RFC 7807 problem-detail on failure.");
  out.push("- All audit events use CloudEvents v1.0 with type `<reverse-domain>.audit.<category>.<event-name>` (e.g., `com.example.audit.compliance.user-pause-issued`).");
  out.push("- All authenticated routes carry a PASETO v4.public session token in an HttpOnly + Secure + SameSite=Lax cookie (never JS-readable storage).");
  out.push("- All exported behaviors carry JSDoc; every spec.yaml carries a `chat_agent` block defining when_to_call / when_not_to_call / natural_language_examples.");
  out.push("");
  return `${out.join("\n")}\n`;
}

// ---------- main ----------

const result = aggregate(REPO_ROOT, SOURCE_ROOTS);
if (result.failures.length > 0) {
  process.stderr.write(`\n❌ generate-agents-manifest: ${result.failures.length} failure(s)\n`);
  for (const f of result.failures) {
    process.stderr.write(`   - ${relative(REPO_ROOT, f.filePath)}\n`);
    process.stderr.write(`       reason: ${f.reason}\n`);
    process.stderr.write(`       detail: ${f.detail}\n`);
  }
  process.exit(1);
}

const primitive = readPrimitiveMeta(REPO_ROOT);
mkdirSync(dirname(OUT_JSON), { recursive: true });
writeFileSync(OUT_JSON, renderJson(result.entries));
writeFileSync(OUT_TXT, renderText(result.entries));
writeFileSync(OUT_LLMS, renderLlmsTxt(result.entries, primitive));
process.stdout.write(
  `✅ generate-agents-manifest — ${result.entries.length} feature(s) → ${relative(REPO_ROOT, OUT_JSON)} + ${relative(REPO_ROOT, OUT_TXT)} + ${relative(REPO_ROOT, OUT_LLMS)}\n`,
);
